select count(*) filter (where slug like any (array['pack2-forever-stamp', 'pack2-netflix-standard', 'pack2-playstation-5', 'pack2-airpods-pro-3', 'pack2-amazon-prime-annual', 'pack2-harvard-year', 'pack2-corvette-stingray-2027', 'pack2-steve-jobs-sandals', 'pack2-diana-sheep-sweater', 'pack2-peloton-bike', 'pack2-ohtani-contract', 'pack2-jordan-1998-jersey', 'pack2-twitter-acquisition', 'pack2-burj-khalifa', 'pack2-eras-tour-gross'])) as questions_in_pack
